), cause_period AS (
  SELECT b.*,p.osa_period,p.osa_period_order
  FROM cause_base b
  JOIN latest x USING(id_customer)
  CROSS JOIN LATERAL (
SELECT 'MTD'::text,1::int
      WHERE DATE_TRUNC('month',b.data)=DATE_TRUNC('month',x.latest_data)
    UNION ALL
    SELECT 'Mês Anterior',2
      WHERE DATE_TRUNC('month',b.data)=DATE_TRUNC('month',x.latest_data-INTERVAL '1 month')
    UNION ALL
    SELECT 'U3M',3
      WHERE b.data>=DATE_TRUNC('month',x.latest_data)-INTERVAL '2 months'
        AND b.data<=x.latest_data
    UNION ALL
    SELECT 'YTD',5
      WHERE EXTRACT(YEAR FROM b.data)=EXTRACT(YEAR FROM x.latest_data)
  ) AS p(osa_period,osa_period_order)
), cause_agg AS (
  SELECT id_customer,osa_period,osa_period_order,hierarquia_1,
         SUM(COALESCE(vl_perda_osa,0))::float8 AS loss_value
  FROM cause_period
  GROUP BY id_customer,osa_period,osa_period_order,hierarquia_1
)
SELECT
  h.id_customer,h.nm_measure,h.osa_period,h.osa_period_order,
  NULL::text AS rede,NULL::text AS bandeira,NULL::text AS uf,NULL::text AS cidade,NULL::text AS tipo_local,NULL::text AS loja,NULL::text AS regiao,NULL::text AS tp_activity_level,NULL::text AS activity_level,NULL::text AS item,NULL::text AS descricao_marca,h.hierarquia_1,NULL::text AS hierarquia_2,NULL::text AS hierarquia_3,
  c.loss_value,
  (h.loss_base*h.conversion_factor)::float8 AS loss_qty,
  (h.problem_base*h.conversion_factor)::float8 AS problem_qty,
  h.problem_base,h.active_base
FROM history_agg h
LEFT JOIN cause_agg c
  ON c.id_customer=h.id_customer
 AND c.osa_period=h.osa_period
 AND c.hierarquia_1 IS NOT DISTINCT FROM h.hierarquia_1
